{
  "facts": [
    {
      "topic": "scope",
      "statement": "The entry reads PNG bytes through a sequential read sequence: read_info, read_update_info, start_read_image, repeated read_row, then read_end.",
      "evidence": [
        {"unit_id": "u-e9cdca141412a92154b2", "start_line": 127, "end_line": 141, "role": "dependency", "dependency_reason": "The harness installs its byte callback and begins the read sequence."},
        {"unit_id": "u-e9cdca141412a92154b2", "start_line": 169, "end_line": 179, "role": "dependency", "dependency_reason": "The harness calls start_read_image before its row loop."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "configuration",
      "statement": "The supplied recipe disables STDIO, WARNING, and WRITE options in pnglibconf.dfa, then configures and builds libpng16.la before linking the fuzzer.",
      "evidence": [
        {"unit_id": "u-d102cd4502b9fe57a4ec", "start_line": 25, "end_line": 43, "role": "dependency", "dependency_reason": "The recipe fixes the build configuration and linked library."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "trigger",
      "statement": "Inputs shorter than eight bytes or failing the eight-byte PNG signature check return before the read sequence. The callback reads the remaining bytes and reports a read error when asked for more than remain.",
      "evidence": [
        {"unit_id": "u-e9cdca141412a92154b2", "start_line": 51, "end_line": 59, "role": "dependency", "dependency_reason": "The callback defines how supplied bytes are consumed."},
        {"unit_id": "u-e9cdca141412a92154b2", "start_line": 61, "end_line": 76, "role": "dependency", "dependency_reason": "The entry gates reading on size and signature."},
        {"unit_id": "u-e9cdca141412a92154b2", "start_line": 127, "end_line": 132, "role": "dependency", "dependency_reason": "The read callback begins after the eight signature bytes."},
        {"unit_id": "u-6adfb4dd1b0110025f7e", "start_line": 73, "end_line": 90, "role": "dependency", "dependency_reason": "The signature comparison checks the PNG signature bytes."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "On both supplied source versions, png_read_info records the first IDAT length and stops its pre-row chunk loop at that chunk.",
      "evidence": [
        {"unit_id": "u-62a04c3f599eb18a9791", "start_line": 162, "end_line": 165, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-ca42179a2998cf81b645", "start_line": 162, "end_line": 165, "role": "primary", "dependency_reason": ""}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "On both versions, png_read_update_info calls png_read_start_row when PNG_FLAG_ROW_INIT is clear; if the flag is already set, it reports a duplicate-call application error.",
      "evidence": [
        {"unit_id": "u-b53e493521e3901bcbc1", "start_line": 266, "end_line": 287, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-d0be9d0c4c1e9dd11c66", "start_line": 266, "end_line": 287, "role": "primary", "dependency_reason": ""}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "On both versions, png_start_read_image calls png_read_start_row only when PNG_FLAG_ROW_INIT is clear. When that flag is set, it calls png_app_error for the duplicate initialization.",
      "evidence": [
        {"unit_id": "u-4a3ce9d69b27b864372c", "start_line": 297, "end_line": 312, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-cc1e0b2b98d159b17936", "start_line": 297, "end_line": 312, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-e9cdca141412a92154b2", "start_line": 139, "end_line": 141, "role": "dependency", "dependency_reason": "The harness calls read_update_info first."},
        {"unit_id": "u-e9cdca141412a92154b2", "start_line": 169, "end_line": 175, "role": "dependency", "dependency_reason": "The harness then calls start_read_image before read_row."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "consequence",
      "statement": "On both versions, png_app_error calls png_warning if PNG_FLAG_APP_ERRORS_WARN is set and png_error otherwise. Thus the effect of the duplicate-call report depends on that flag.",
      "evidence": [
        {"unit_id": "u-d1a66dd20f4a316243f6", "start_line": 404, "end_line": 410, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-e6c0ac9c7518d20d0873", "start_line": 404, "end_line": 410, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-4a3ce9d69b27b864372c", "start_line": 304, "end_line": 310, "role": "dependency", "dependency_reason": "The duplicate-call branch invokes png_app_error."},
        {"unit_id": "u-cc1e0b2b98d159b17936", "start_line": 304, "end_line": 310, "role": "dependency", "dependency_reason": "The same duplicate-call branch is present after the change."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "configuration",
      "statement": "Read-structure creation conditionally sets PNG_FLAG_BENIGN_ERRORS_WARN and, for a release build, PNG_FLAG_APP_WARNINGS_WARN. These shown assignments do not establish the initial value of the distinct PNG_FLAG_APP_ERRORS_WARN flag.",
      "evidence": [
        {"unit_id": "u-4a3ce9d69b27b864372c", "start_line": 24, "end_line": 75, "role": "dependency", "dependency_reason": "The read-structure constructor calls png_create_png_struct and then makes the shown conditional flag assignments."},
        {"unit_id": "u-cc1e0b2b98d159b17936", "start_line": 24, "end_line": 75, "role": "dependency", "dependency_reason": "The same creation path and assignments appear after the change."},
        {"unit_id": "u-d1a66dd20f4a316243f6", "start_line": 404, "end_line": 410, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-e6c0ac9c7518d20d0873", "start_line": 404, "end_line": 410, "role": "primary", "dependency_reason": ""}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "alternative",
      "statement": "png_read_row itself calls png_read_start_row if PNG_FLAG_ROW_INIT is clear, so the source provides a route to row initialization through read_row. Whether the fixed harness reaches that route is governed by its earlier calls.",
      "evidence": [
        {"unit_id": "u-abc567e3e0e39c327584", "start_line": 382, "end_line": 405, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-f907d51074ecef0236f2", "start_line": 382, "end_line": 405, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-e9cdca141412a92154b2", "start_line": 139, "end_line": 141, "role": "dependency", "dependency_reason": "The harness calls read_update_info before row reading."},
        {"unit_id": "u-e9cdca141412a92154b2", "start_line": 169, "end_line": 175, "role": "dependency", "dependency_reason": "The harness also calls start_read_image before row reading."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "After initialization, png_read_row requires IDAT state, consumes IDAT data, combines the decoded row into a provided row buffer, and advances row state.",
      "evidence": [
        {"unit_id": "u-abc567e3e0e39c327584", "start_line": 538, "end_line": 551, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-abc567e3e0e39c327584", "start_line": 586, "end_line": 614, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-f907d51074ecef0236f2", "start_line": 538, "end_line": 551, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-f907d51074ecef0236f2", "start_line": 586, "end_line": 614, "role": "primary", "dependency_reason": ""}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "scope",
      "statement": "The harness rejects an image when width times height exceeds 100000000, then uses the pass count and height for its row-reading loop.",
      "evidence": [
        {"unit_id": "u-e9cdca141412a92154b2", "start_line": 152, "end_line": 175, "role": "dependency", "dependency_reason": "The dimensions and pass count control whether the target attempts rows."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "consequence",
      "statement": "The harness has setjmp cleanup branches that return 0, and its normal path also returns 0 after read_end. The supplied calls alone do not show whether a duplicate-call png_error transfers control to those branches.",
      "evidence": [
        {"unit_id": "u-e9cdca141412a92154b2", "start_line": 134, "end_line": 150, "role": "dependency", "dependency_reason": "The entry installs its error recovery points."},
        {"unit_id": "u-e9cdca141412a92154b2", "start_line": 169, "end_line": 185, "role": "dependency", "dependency_reason": "The row loop and normal return follow the duplicate-call site."},
        {"unit_id": "u-d1a66dd20f4a316243f6", "start_line": 404, "end_line": 410, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-e6c0ac9c7518d20d0873", "start_line": 404, "end_line": 410, "role": "primary", "dependency_reason": ""}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "counterevidence",
      "statement": "The complete fixed harness contains no explicit assert statement or check that a row was decoded successfully; it calls read_row and later returns 0 on the normal path.",
      "evidence": [
        {"unit_id": "u-e9cdca141412a92154b2", "start_line": 1, "end_line": 186, "role": "dependency", "dependency_reason": "The entire audited harness is needed to support the limited absence claim."}
      ],
      "absence_claim": true,
      "audited_unit_ids": ["u-e9cdca141412a92154b2"]
    }
  ],
  "missing_information": [
    "The before and after png_read_start_row bodies are needed to establish whether that call sets PNG_FLAG_ROW_INIT under the frozen condition.",
    "The initial PNG_FLAG_APP_ERRORS_WARN value from png_create_png_struct and any applicable initialization or configuration is needed to determine which png_app_error branch this harness takes.",
    "The applicable png_error and png_warning implementations or macros are needed to determine whether the duplicate-call report stops row reading in this build."
  ],
  "requested_symbols": [
    "png_read_start_row",
    "PNG_FLAG_ROW_INIT",
    "PNG_FLAG_APP_ERRORS_WARN",
    "png_create_png_struct",
    "png_error",
    "png_warning"
  ],
  "requested_paths": [
    "pngrutil.c",
    "png.c",
    "pngerror.c",
    "pngpriv.h"
  ]
}
